    99→    validator_deposits_to_process: HashMap<usize, u64>,
   100→    /// The deposits to append to `pending_deposits` after processing all applicable deposits.
   101→    deposits_to_postpone: Vec<PendingDeposit>,
   102→    /// New validators to be added to the state *after* processing completes.
   103→    new_validator_deposits: Vec<PendingDeposit>,
