   125→
   126→impl ValidatorInfo {
   127→    #[inline]
   128→    pub fn is_unslashed_participating_index(&self, flag_index: usize) -> Result<bool, Error> {
   129→        Ok(self.is_active_previous_epoch
   130→            && !self.is_slashed
   131→            && self
   132→                .previous_epoch_participation
   133→                .has_flag(flag_index)
   134→                .map_err(|_| Error::InvalidFlagIndex(flag_index))?)
   135→    }
