   138→#[instrument(skip_all)]
   139→pub fn process_epoch_single_pass<E: EthSpec>(
   140→    state: &mut BeaconState<E>,
   141→    spec: &ChainSpec,
   142→    conf: SinglePassConfig,
   143→) -> Result<ParticipationEpochSummary<E>, Error> {
   144→    initialize_epoch_cache(state, spec)?;
   145→    initialize_progressive_balances_cache(state, spec)?;
   146→    state.build_exit_cache(spec)?;
   147→    state.build_committee_cache(RelativeEpoch::Previous, spec)?;
   148→    state.build_committee_cache(RelativeEpoch::Current, spec)?;
   149→    state.update_pubkey_cache()?;
   150→
   151→    let previous_epoch = state.previous_epoch();
   152→    let current_epoch = state.current_epoch();
   153→    let next_epoch = state.next_epoch()?;
   154→    let is_in_inactivity_leak = state.is_in_inactivity_leak(previous_epoch, spec)?;
   155→    let total_active_balance = state.get_total_active_balance()?;
   156→    let churn_limit = state.get_validator_churn_limit(spec)?;
   157→    let activation_churn_limit = state.get_activation_churn_limit(spec)?;
   158→    let finalized_checkpoint = state.finalized_checkpoint();
   159→    let fork_name = state.fork_name_unchecked();
   160→
   161→    let state_ctxt = &StateContext {
   162→        current_epoch,
   163→        next_epoch,
   164→        finalized_checkpoint,
   165→        is_in_inactivity_leak,
   166→        total_active_balance,
   167→        churn_limit,
   168→        fork_name,
   169→    };
   170→
   171→    // Contexts that require immutable access to `state`.
   172→    let slashings_ctxt = &SlashingsContext::new(state, state_ctxt, spec)?;
   173→    let mut next_epoch_cache = PreEpochCache::new_for_next_epoch(state)?;
   174→
   175→    let pending_deposits_ctxt = if fork_name.electra_enabled() && conf.pending_deposits {
   176→        Some(PendingDepositsContext::new(state, spec, &conf)?)
   177→    } else {
   178→        None
   179→    };
   180→
   181→    let mut earliest_exit_epoch = state.earliest_exit_epoch().ok();
   182→    let mut exit_balance_to_consume = state.exit_balance_to_consume().ok();
   183→    let validators_in_consolidations = get_validators_in_consolidations(state);
   184→
   185→    // Split the state into several disjoint mutable borrows.
   186→    let (
   187→        validators,
   188→        balances,
   189→        previous_epoch_participation,
   190→        current_epoch_participation,
   191→        inactivity_scores,
   192→        progressive_balances,
   193→        exit_cache,
   194→        epoch_cache,
   195→    ) = state.mutable_validator_fields()?;
   196→
   197→    let num_validators = validators.len();
   198→
   199→    // Take a snapshot of the validators and participation before mutating. This is used for
   200→    // informational purposes (e.g. by the validator monitor).
   201→    let summary = ParticipationEpochSummary::new(
   202→        validators.clone(),
   203→        previous_epoch_participation.clone(),
   204→        current_epoch_participation.clone(),
   205→        previous_epoch,
   206→        current_epoch,
   207→    );
   208→
   209→    // Compute shared values required for different parts of epoch processing.
   210→    let rewards_ctxt = &RewardsAndPenaltiesContext::new(progressive_balances, state_ctxt, spec)?;
   211→
   212→    let mut activation_queues = if !fork_name.electra_enabled() {
   213→        let activation_queue = epoch_cache
   214→            .activation_queue()?
   215→            .get_validators_eligible_for_activation(
   216→                finalized_checkpoint.epoch,
   217→                activation_churn_limit as usize,
   218→            );
   219→        let next_epoch_activation_queue = ActivationQueue::default();
   220→        Some((activation_queue, next_epoch_activation_queue))
   221→    } else {
   222→        None
   223→    };
   224→    let effective_balances_ctxt = &EffectiveBalancesContext::new(spec)?;
   225→
   226→    // Iterate over the validators and related fields in one pass.
   227→    let mut validators_iter = validators.iter_cow();
   228→    let mut balances_iter = balances.iter_cow();
   229→    let mut inactivity_scores_iter = inactivity_scores.iter_cow();
   230→
   231→    for (index, &previous_epoch_participation, &current_epoch_participation) in izip!(
   232→        0..num_validators,
   233→        previous_epoch_participation.iter(),
   234→        current_epoch_participation.iter(),
   235→    ) {
   236→        let (_, mut validator) = validators_iter
   237→            .next_cow()
   238→            .ok_or(BeaconStateError::UnknownValidator(index))?;
   239→        let (_, mut balance) = balances_iter
   240→            .next_cow()
   241→            .ok_or(BeaconStateError::UnknownValidator(index))?;
   242→        let (_, mut inactivity_score) = inactivity_scores_iter
   243→            .next_cow()
   244→            .ok_or(BeaconStateError::UnknownValidator(index))?;
   245→
   246→        let is_active_current_epoch = validator.is_active_at(current_epoch);
   247→        let is_active_previous_epoch = validator.is_active_at(previous_epoch);
   248→        let is_eligible = is_active_previous_epoch
   249→            || (validator.slashed && previous_epoch.safe_add(1)? < validator.withdrawable_epoch);
   250→
   251→        let base_reward = if is_eligible {
   252→            epoch_cache.get_base_reward(index)?
   253→        } else {
   254→            0
   255→        };
   256→
   257→        let validator_info = &ValidatorInfo {
   258→            index,
   259→            effective_balance: validator.effective_balance,
   260→            base_reward,
   261→            is_eligible,
   262→            is_slashed: validator.slashed,
   263→            is_active_current_epoch,
   264→            is_active_previous_epoch,
   265→            previous_epoch_participation,
   266→            current_epoch_participation,
   267→        };
   268→
   269→        if current_epoch != E::genesis_epoch() {
   270→            // `process_inactivity_updates`
   271→            if conf.inactivity_updates {
   272→                process_single_inactivity_update(
   273→                    &mut inactivity_score,
   274→                    validator_info,
   275→                    state_ctxt,
   276→                    spec,
   277→                )?;
   278→            }
   279→
   280→            // `process_rewards_and_penalties`
   281→            if conf.rewards_and_penalties {
   282→                process_single_reward_and_penalty(
   283→                    &mut balance,
   284→                    &inactivity_score,
   285→                    validator_info,
   286→                    rewards_ctxt,
   287→                    state_ctxt,
   288→                    spec,
   289→                )?;
   290→            }
   291→        }
   292→
   293→        // `process_registry_updates`
   294→        if conf.registry_updates {
   295→            let activation_queue_refs = activation_queues
   296→                .as_mut()
   297→                .map(|(current_queue, next_queue)| (&*current_queue, next_queue));
   298→            process_single_registry_update(
   299→                &mut validator,
   300→                validator_info,
   301→                exit_cache,
   302→                activation_queue_refs,
   303→                state_ctxt,
   304→                earliest_exit_epoch.as_mut(),
   305→                exit_balance_to_consume.as_mut(),
   306→                spec,
   307→            )?;
   308→        }
   309→
   310→        // `process_slashings`
   311→        if conf.slashings {
   312→            process_single_slashing(&mut balance, &validator, slashings_ctxt, state_ctxt, spec)?;
   313→        }
   314→
   315→        // `process_pending_deposits`
   316→        if let Some(pending_balance_deposits_ctxt) = &pending_deposits_ctxt {
   317→            process_pending_deposits_for_validator(
   318→                &mut balance,
   319→                validator_info,
   320→                pending_balance_deposits_ctxt,
   321→            )?;
   322→        }
   323→
   324→        // `process_effective_balance_updates`
   325→        if conf.effective_balance_updates {
   326→            if validators_in_consolidations.contains(&validator_info.index) {
   327→                process_single_dummy_effective_balance_update(
   328→                    validator_info.index,
   329→                    &validator,
   330→                    &mut next_epoch_cache,
   331→                    state_ctxt,
   332→                )?;
   333→            } else {
   334→                process_single_effective_balance_update(
   335→                    validator_info.index,
   336→                    *balance,
   337→                    &mut validator,
   338→                    validator_info.current_epoch_participation,
   339→                    &mut next_epoch_cache,
   340→                    progressive_balances,
   341→                    effective_balances_ctxt,
   342→                    state_ctxt,
   343→                    spec,
   344→                )?;
   345→            }
   346→        }
   347→    }
   348→
   349→    if conf.registry_updates && fork_name.electra_enabled() {
   350→        if let Ok(earliest_exit_epoch_state) = state.earliest_exit_epoch_mut() {
   351→            *earliest_exit_epoch_state =
   352→                earliest_exit_epoch.ok_or(Error::MissingEarliestExitEpoch)?;
   353→        }
   354→        if let Ok(exit_balance_to_consume_state) = state.exit_balance_to_consume_mut() {
   355→            *exit_balance_to_consume_state =
   356→                exit_balance_to_consume.ok_or(Error::MissingExitBalanceToConsume)?;
   357→        }
   358→    }
   359→
   360→    // Finish processing pending balance deposits if relevant.
   361→    //
   362→    // This *could* be reordered after `process_pending_consolidations` which pushes only to the end
   363→    // of the `pending_deposits` list. But we may as well preserve the write ordering used
   364→    // by the spec and do this first.
   365→    if let Some(ctxt) = pending_deposits_ctxt {
   366→        let mut new_balance_deposits = List::try_from_iter(
   367→            state
   368→                .pending_deposits()?
   369→                .iter_from(ctxt.next_deposit_index)?
   370→                .cloned(),
   371→        )?;
   372→        for deposit in ctxt.deposits_to_postpone {
   373→            new_balance_deposits.push(deposit)?;
   374→        }
   375→        *state.pending_deposits_mut()? = new_balance_deposits;
   376→        *state.deposit_balance_to_consume_mut()? = ctxt.deposit_balance_to_consume;
   377→
   378→        // `new_validator_deposits` may contain multiple deposits with the same pubkey where
   379→        // the first deposit creates the new validator and the others are topups.
   380→        // Each item in the vec is a (pubkey, validator_index)
   381→        let mut added_validators = Vec::new();
   382→        for deposit in ctxt.new_validator_deposits {
   383→            let deposit_data = DepositData {
   384→                pubkey: deposit.pubkey,
   385→                withdrawal_credentials: deposit.withdrawal_credentials,
   386→                amount: deposit.amount,
   387→                signature: deposit.signature,
   388→            };
   389→            // Only check the signature if this is the first deposit for the validator,
   390→            // following the logic from `apply_pending_deposit` in the spec.
   391→            if let Some(validator_index) = state.get_validator_index(&deposit_data.pubkey)? {
   392→                state
   393→                    .get_balance_mut(validator_index)?
   394→                    .safe_add_assign(deposit_data.amount)?;
   395→            } else if is_valid_deposit_signature(&deposit_data, spec).is_ok() {
   396→                // Apply the new deposit to the state
   397→                let validator_index = state.add_validator_to_registry(
   398→                    deposit_data.pubkey,
   399→                    deposit_data.withdrawal_credentials,
   400→                    deposit_data.amount,
   401→                    spec,
   402→                )?;
   403→                added_validators.push((deposit_data.pubkey, validator_index));
   404→            }
   405→        }
   406→        if conf.effective_balance_updates {
   407→            // Re-process effective balance updates for validators affected by top-up of new validators.
   408→            let (
   409→                validators,
   410→                balances,
   411→                _,
   412→                current_epoch_participation,
   413→                _,
   414→                progressive_balances,
   415→                _,
   416→                _,
   417→            ) = state.mutable_validator_fields()?;
   418→            for (_, validator_index) in added_validators.iter() {
   419→                let balance = *balances
   420→                    .get(*validator_index)
   421→                    .ok_or(BeaconStateError::UnknownValidator(*validator_index))?;
   422→                let mut validator = validators
   423→                    .get_cow(*validator_index)
   424→                    .ok_or(BeaconStateError::UnknownValidator(*validator_index))?;
   425→                let validator_current_epoch_participation = *current_epoch_participation
   426→                    .get(*validator_index)
   427→                    .ok_or(BeaconStateError::UnknownValidator(*validator_index))?;
   428→                process_single_effective_balance_update(
   429→                    *validator_index,
   430→                    balance,
   431→                    &mut validator,
   432→                    validator_current_epoch_participation,
   433→                    &mut next_epoch_cache,
   434→                    progressive_balances,
   435→                    effective_balances_ctxt,
   436→                    state_ctxt,
   437→                    spec,
   438→                )?;
   439→            }
   440→        }
   441→    }
   442→
   443→    // Process consolidations outside the single-pass loop, as they depend on balances for multiple
   444→    // validators and cannot be computed accurately inside the loop.
   445→    if fork_name.electra_enabled() && conf.pending_consolidations {
   446→        process_pending_consolidations(
   447→            state,
   448→            &validators_in_consolidations,
   449→            &mut next_epoch_cache,
   450→            effective_balances_ctxt,
   451→            conf.effective_balance_updates,
   452→            state_ctxt,
   453→            spec,
   454→        )?;
   455→    }
   456→
   457→    // Finally, finish updating effective balance caches. We need this to happen *after* processing
   458→    // of pending consolidations, which recomputes some effective balances.
   459→    if conf.effective_balance_updates {
   460→        let next_epoch_total_active_balance = next_epoch_cache.get_total_active_balance();
   461→        state.set_total_active_balance(next_epoch, next_epoch_total_active_balance, spec);
   462→        let next_epoch_activation_queue =
   463→            activation_queues.map_or_else(ActivationQueue::default, |(_, queue)| queue);
   464→        *state.epoch_cache_mut() =
   465→            next_epoch_cache.into_epoch_cache(next_epoch_activation_queue, spec)?;
   466→    }
   467→
   468→    if conf.proposer_lookahead && fork_name.fulu_enabled() {
   469→        process_proposer_lookahead(state, spec)?;
   470→    }
   471→
   472→    Ok(summary)
   473→}
   474→
   475→// TOOO(EIP-7917): use balances cache
   476→pub fn process_proposer_lookahead<E: EthSpec>(
   477→    state: &mut BeaconState<E>,
   478→    spec: &ChainSpec,
   479→) -> Result<(), Error> {
   480→    let mut lookahead = state.proposer_lookahead()?.clone().to_vec();
   481→
   482→    // Shift out proposers in the first epoch
   483→    lookahead.copy_within((E::slots_per_epoch() as usize).., 0);
   484→
   485→    let next_epoch = state
   486→        .current_epoch()
   487→        .safe_add(spec.min_seed_lookahead.as_u64())?
   488→        .safe_add(1)?;
   489→    let last_epoch_proposers = state.get_beacon_proposer_indices(next_epoch, spec)?;
   490→
   491→    // Fill in the last epoch with new proposer indices
   492→    let last_epoch_start = E::proposer_lookahead_slots().safe_sub(E::slots_per_epoch() as usize)?;
   493→    for (i, proposer) in last_epoch_proposers.into_iter().enumerate() {
   494→        let index = last_epoch_start.safe_add(i)?;
   495→        *lookahead
   496→            .get_mut(index)
   497→            .ok_or(Error::ProposerLookaheadOutOfBounds(index))? = proposer as u64;
   498→    }
   499→
   500→    *state.proposer_lookahead_mut()? = Vector::new(lookahead)?;
   501→
   502→    Ok(())
   503→}
   504→
   505→fn process_single_inactivity_update(
   506→    inactivity_score: &mut Cow<u64>,
   507→    validator_info: &ValidatorInfo,
   508→    state_ctxt: &StateContext,
   509→    spec: &ChainSpec,
   510→) -> Result<(), Error> {
   511→    if !validator_info.is_eligible {
   512→        return Ok(());
   513→    }
   514→
   515→    // Increase inactivity score of inactive validators
   516→    if validator_info.is_unslashed_participating_index(TIMELY_TARGET_FLAG_INDEX)? {
   517→        // Avoid mutating when the inactivity score is 0 and can't go any lower -- the common
   518→        // case.
   519→        if **inactivity_score == 0 {
   520→            return Ok(());
   521→        }
   522→        inactivity_score.make_mut()?.safe_sub_assign(1)?;
   523→    } else {
   524→        inactivity_score
   525→            .make_mut()?
   526→            .safe_add_assign(spec.inactivity_score_bias)?;
   527→    }
   528→
   529→    // Decrease the score of all validators for forgiveness when not during a leak
   530→    if !state_ctxt.is_in_inactivity_leak {
   531→        let deduction = min(spec.inactivity_score_recovery_rate, **inactivity_score);
   532→        inactivity_score.make_mut()?.safe_sub_assign(deduction)?;
   533→    }
   534→
   535→    Ok(())
   536→}
   537→
   538→fn process_single_reward_and_penalty(
   539→    balance: &mut Cow<u64>,
   540→    inactivity_score: &u64,
   541→    validator_info: &ValidatorInfo,
   542→    rewards_ctxt: &RewardsAndPenaltiesContext,
   543→    state_ctxt: &StateContext,
   544→    spec: &ChainSpec,
   545→) -> Result<(), Error> {
   546→    if !validator_info.is_eligible {
   547→        return Ok(());
   548→    }
   549→
   550→    let mut delta = Delta::default();
   551→    for flag_index in 0..NUM_FLAG_INDICES {
   552→        get_flag_index_delta(
   553→            &mut delta,
   554→            validator_info,
   555→            flag_index,
   556→            rewards_ctxt,
   557→            state_ctxt,
   558→        )?;
   559→    }
   560→    get_inactivity_penalty_delta(
   561→        &mut delta,
   562→        validator_info,
   563→        inactivity_score,
   564→        state_ctxt,
   565→        spec,
   566→    )?;
   567→
   568→    if delta.rewards != 0 || delta.penalties != 0 {
   569→        let balance = balance.make_mut()?;
   570→        balance.safe_add_assign(delta.rewards)?;
   571→        *balance = balance.saturating_sub(delta.penalties);
   572→    }
   573→
   574→    Ok(())
   575→}
   576→
   577→fn get_flag_index_delta(
   578→    delta: &mut Delta,
   579→    validator_info: &ValidatorInfo,
   580→    flag_index: usize,
   581→    rewards_ctxt: &RewardsAndPenaltiesContext,
   582→    state_ctxt: &StateContext,
   583→) -> Result<(), Error> {
   584→    let base_reward = validator_info.base_reward;
   585→    let weight = get_flag_weight(flag_index)?;
   586→    let unslashed_participating_increments =
   587→        rewards_ctxt.get_unslashed_participating_increments(flag_index)?;
   588→
   589→    if validator_info.is_unslashed_participating_index(flag_index)? {
   590→        if !state_ctxt.is_in_inactivity_leak {
   591→            let reward_numerator = base_reward
   592→                .safe_mul(weight)?
   593→                .safe_mul(unslashed_participating_increments)?;
   594→            delta.reward(
   595→                reward_numerator.safe_div(
   596→                    rewards_ctxt
   597→                        .active_increments
   598→                        .safe_mul(WEIGHT_DENOMINATOR)?,
   599→                )?,
   600→            )?;
   601→        }
   602→    } else if flag_index != TIMELY_HEAD_FLAG_INDEX {
   603→        delta.penalize(base_reward.safe_mul(weight)?.safe_div(WEIGHT_DENOMINATOR)?)?;
   604→    }
   605→    Ok(())
   606→}
   607→
   608→/// Get the weight for a `flag_index` from the constant list of all weights.
   609→fn get_flag_weight(flag_index: usize) -> Result<u64, Error> {
   610→    PARTICIPATION_FLAG_WEIGHTS
   611→        .get(flag_index)
   612→        .copied()
   613→        .ok_or(Error::InvalidFlagIndex(flag_index))
   614→}
   615→
   616→fn get_inactivity_penalty_delta(
   617→    delta: &mut Delta,
   618→    validator_info: &ValidatorInfo,
   619→    inactivity_score: &u64,
   620→    state_ctxt: &StateContext,
   621→    spec: &ChainSpec,
   622→) -> Result<(), Error> {
   623→    if !validator_info.is_unslashed_participating_index(TIMELY_TARGET_FLAG_INDEX)? {
   624→        let penalty_numerator = validator_info
   625→            .effective_balance
   626→            .safe_mul(*inactivity_score)?;
   627→        let penalty_denominator = spec
   628→            .inactivity_score_bias
   629→            .safe_mul(spec.inactivity_penalty_quotient_for_fork(state_ctxt.fork_name))?;
   630→        delta.penalize(penalty_numerator.safe_div(penalty_denominator)?)?;
   631→    }
   632→    Ok(())
   633→}
   634→
   635→impl RewardsAndPenaltiesContext {
   636→    fn new(
   637→        progressive_balances: &ProgressiveBalancesCache,
   638→        state_ctxt: &StateContext,
   639→        spec: &ChainSpec,
   640→    ) -> Result<Self, Error> {
   641→        let mut unslashed_participating_increments_array = [0; NUM_FLAG_INDICES];
   642→        for flag_index in 0..NUM_FLAG_INDICES {
   643→            let unslashed_participating_balance =
   644→                progressive_balances.previous_epoch_flag_attesting_balance(flag_index)?;
   645→            let unslashed_participating_increments =
   646→                unslashed_participating_balance.safe_div(spec.effective_balance_increment)?;
   647→
   648→            *unslashed_participating_increments_array
   649→                .get_mut(flag_index)
   650→                .ok_or(Error::InvalidFlagIndex(flag_index))? = unslashed_participating_increments;
   651→        }
   652→        let active_increments = state_ctxt
   653→            .total_active_balance
   654→            .safe_div(spec.effective_balance_increment)?;
   655→
   656→        Ok(Self {
   657→            unslashed_participating_increments_array,
   658→            active_increments,
   659→        })
   660→    }
   661→
   662→    fn get_unslashed_participating_increments(&self, flag_index: usize) -> Result<u64, Error> {
   663→        self.unslashed_participating_increments_array
   664→            .get(flag_index)
   665→            .copied()
   666→            .ok_or(Error::InvalidFlagIndex(flag_index))
   667→    }
   668→}
   669→
   670→#[allow(clippy::too_many_arguments)]
   671→fn process_single_registry_update(
   672→    validator: &mut Cow<Validator>,
   673→    validator_info: &ValidatorInfo,
   674→    exit_cache: &mut ExitCache,
   675→    activation_queues: Option<(&BTreeSet<usize>, &mut ActivationQueue)>,
   676→    state_ctxt: &StateContext,
   677→    earliest_exit_epoch: Option<&mut Epoch>,
   678→    exit_balance_to_consume: Option<&mut u64>,
   679→    spec: &ChainSpec,
   680→) -> Result<(), Error> {
   681→    if !state_ctxt.fork_name.electra_enabled() {
   682→        let (activation_queue, next_epoch_activation_queue) =
   683→            activation_queues.ok_or(Error::SinglePassMissingActivationQueue)?;
   684→        process_single_registry_update_pre_electra(
   685→            validator,
   686→            validator_info,
   687→            exit_cache,
   688→            activation_queue,
   689→            next_epoch_activation_queue,
   690→            state_ctxt,
   691→            spec,
   692→        )
   693→    } else {
   694→        process_single_registry_update_post_electra(
   695→            validator,
   696→            exit_cache,
   697→            state_ctxt,
   698→            earliest_exit_epoch.ok_or(Error::MissingEarliestExitEpoch)?,
   699→            exit_balance_to_consume.ok_or(Error::MissingExitBalanceToConsume)?,
   700→            spec,
   701→        )
   702→    }
   703→}
   704→
   705→fn process_single_registry_update_pre_electra(
   706→    validator: &mut Cow<Validator>,
   707→    validator_info: &ValidatorInfo,
   708→    exit_cache: &mut ExitCache,
   709→    activation_queue: &BTreeSet<usize>,
   710→    next_epoch_activation_queue: &mut ActivationQueue,
   711→    state_ctxt: &StateContext,
   712→    spec: &ChainSpec,
   713→) -> Result<(), Error> {
   714→    let current_epoch = state_ctxt.current_epoch;
   715→
   716→    if validator.is_eligible_for_activation_queue(spec, state_ctxt.fork_name) {
   717→        validator.make_mut()?.activation_eligibility_epoch = current_epoch.safe_add(1)?;
   718→    }
   719→
   720→    if validator.is_active_at(current_epoch) && validator.effective_balance <= spec.ejection_balance
   721→    {
   722→        initiate_validator_exit(validator, exit_cache, state_ctxt, None, None, spec)?;
   723→    }
   724→
   725→    if activation_queue.contains(&validator_info.index) {
   726→        validator.make_mut()?.activation_epoch =
   727→            spec.compute_activation_exit_epoch(current_epoch)?;
   728→    }
   729→
   730→    // Caching: add to speculative activation queue for next epoch.
   731→    next_epoch_activation_queue.add_if_could_be_eligible_for_activation(
   732→        validator_info.index,
   733→        validator,
   734→        state_ctxt.next_epoch,
   735→        spec,
   736→    );
   737→
   738→    Ok(())
   739→}
   740→
   741→fn process_single_registry_update_post_electra(
   742→    validator: &mut Cow<Validator>,
   743→    exit_cache: &mut ExitCache,
   744→    state_ctxt: &StateContext,
   745→    earliest_exit_epoch: &mut Epoch,
   746→    exit_balance_to_consume: &mut u64,
   747→    spec: &ChainSpec,
   748→) -> Result<(), Error> {
   749→    let current_epoch = state_ctxt.current_epoch;
   750→
   751→    if validator.is_eligible_for_activation_queue(spec, state_ctxt.fork_name) {
   752→        validator.make_mut()?.activation_eligibility_epoch = current_epoch.safe_add(1)?;
   753→    }
   754→
   755→    if validator.is_active_at(current_epoch) && validator.effective_balance <= spec.ejection_balance
   756→    {
   757→        initiate_validator_exit(
   758→            validator,
   759→            exit_cache,
   760→            state_ctxt,
   761→            Some(earliest_exit_epoch),
   762→            Some(exit_balance_to_consume),
   763→            spec,
   764→        )?;
   765→    }
   766→
   767→    if validator.is_eligible_for_activation_with_finalized_checkpoint(
   768→        &state_ctxt.finalized_checkpoint,
   769→        spec,
   770→    ) {
   771→        validator.make_mut()?.activation_epoch =
   772→            spec.compute_activation_exit_epoch(current_epoch)?;
   773→    }
   774→
   775→    Ok(())
   776→}
   777→
   778→fn initiate_validator_exit(
   779→    validator: &mut Cow<Validator>,
   780→    exit_cache: &mut ExitCache,
   781→    state_ctxt: &StateContext,
   782→    earliest_exit_epoch: Option<&mut Epoch>,
   783→    exit_balance_to_consume: Option<&mut u64>,
   784→    spec: &ChainSpec,
   785→) -> Result<(), Error> {
   786→    // Return if the validator already initiated exit
   787→    if validator.exit_epoch != spec.far_future_epoch {
   788→        return Ok(());
   789→    }
   790→
   791→    let exit_queue_epoch = if state_ctxt.fork_name.electra_enabled() {
   792→        compute_exit_epoch_and_update_churn(
   793→            validator,
   794→            state_ctxt,
   795→            earliest_exit_epoch.ok_or(Error::MissingEarliestExitEpoch)?,
   796→            exit_balance_to_consume.ok_or(Error::MissingExitBalanceToConsume)?,
   797→            spec,
   798→        )?
   799→    } else {
   800→        // Compute exit queue epoch
   801→        let delayed_epoch = spec.compute_activation_exit_epoch(state_ctxt.current_epoch)?;
   802→        let mut exit_queue_epoch = exit_cache
   803→            .max_epoch()?
   804→            .map_or(delayed_epoch, |epoch| max(epoch, delayed_epoch));
   805→        let exit_queue_churn = exit_cache.get_churn_at(exit_queue_epoch)?;
   806→
   807→        if exit_queue_churn >= state_ctxt.churn_limit {
   808→            exit_queue_epoch.safe_add_assign(1)?;
   809→        }
   810→        exit_queue_epoch
   811→    };
   812→
   813→    let validator = validator.make_mut()?;
   814→    validator.exit_epoch = exit_queue_epoch;
   815→    validator.withdrawable_epoch =
   816→        exit_queue_epoch.safe_add(spec.min_validator_withdrawability_delay)?;
   817→
   818→    exit_cache.record_validator_exit(exit_queue_epoch)?;
   819→    Ok(())
   820→}
   821→
   822→fn compute_exit_epoch_and_update_churn(
   823→    validator: &mut Cow<Validator>,
   824→    state_ctxt: &StateContext,
   825→    earliest_exit_epoch_state: &mut Epoch,
   826→    exit_balance_to_consume_state: &mut u64,
   827→    spec: &ChainSpec,
   828→) -> Result<Epoch, Error> {
   829→    let exit_balance = validator.effective_balance;
   830→    let mut earliest_exit_epoch = std::cmp::max(
   831→        *earliest_exit_epoch_state,
   832→        spec.compute_activation_exit_epoch(state_ctxt.current_epoch)?,
   833→    );
   834→
   835→    let per_epoch_churn = get_activation_exit_churn_limit(state_ctxt, spec)?;
   836→    // New epoch for exits
   837→    let mut exit_balance_to_consume = if *earliest_exit_epoch_state < earliest_exit_epoch {
   838→        per_epoch_churn
   839→    } else {
   840→        *exit_balance_to_consume_state
   841→    };
   842→
   843→    // Exit doesn't fit in the current earliest epoch
   844→    if exit_balance > exit_balance_to_consume {
   845→        let balance_to_process = exit_balance.safe_sub(exit_balance_to_consume)?;
   846→        let additional_epochs = balance_to_process
   847→            .safe_sub(1)?
   848→            .safe_div(per_epoch_churn)?
   849→            .safe_add(1)?;
   850→        earliest_exit_epoch.safe_add_assign(additional_epochs)?;
   851→        exit_balance_to_consume.safe_add_assign(additional_epochs.safe_mul(per_epoch_churn)?)?;
   852→    }
   853→    // Consume the balance and update state variables
   854→    *exit_balance_to_consume_state = exit_balance_to_consume.safe_sub(exit_balance)?;
   855→    *earliest_exit_epoch_state = earliest_exit_epoch;
   856→
   857→    Ok(earliest_exit_epoch)
   858→}
   859→
   860→fn get_activation_exit_churn_limit(
   861→    state_ctxt: &StateContext,
   862→    spec: &ChainSpec,
   863→) -> Result<u64, Error> {
   864→    Ok(std::cmp::min(
   865→        spec.max_per_epoch_activation_exit_churn_limit,
   866→        get_balance_churn_limit(state_ctxt, spec)?,
   867→    ))
   868→}
   869→
   870→fn get_balance_churn_limit(state_ctxt: &StateContext, spec: &ChainSpec) -> Result<u64, Error> {
   871→    let total_active_balance = state_ctxt.total_active_balance;
   872→    let churn = std::cmp::max(
   873→        spec.min_per_epoch_churn_limit_electra,
   874→        total_active_balance.safe_div(spec.churn_limit_quotient)?,
   875→    );
   876→
   877→    Ok(churn.safe_sub(churn.safe_rem(spec.effective_balance_increment)?)?)
   878→}
   879→
   880→impl SlashingsContext {
   881→    fn new<E: EthSpec>(
   882→        state: &BeaconState<E>,
   883→        state_ctxt: &StateContext,
   884→        spec: &ChainSpec,
   885→    ) -> Result<Self, Error> {
   886→        let sum_slashings = state.get_all_slashings().iter().copied().safe_sum()?;
   887→        let adjusted_total_slashing_balance = min(
   888→            sum_slashings.safe_mul(spec.proportional_slashing_multiplier_for_state(state))?,
   889→            state_ctxt.total_active_balance,
   890→        );
   891→
   892→        let target_withdrawable_epoch = state_ctxt
   893→            .current_epoch
   894→            .safe_add(E::EpochsPerSlashingsVector::to_u64().safe_div(2)?)?;
   895→
   896→        let penalty_per_effective_balance_increment = adjusted_total_slashing_balance.safe_div(
   897→            state_ctxt
   898→                .total_active_balance
   899→                .safe_div(spec.effective_balance_increment)?,
   900→        )?;
   901→
   902→        Ok(Self {
   903→            adjusted_total_slashing_balance,
   904→            target_withdrawable_epoch,
   905→            penalty_per_effective_balance_increment,
   906→        })
   907→    }
   908→}
   909→
   910→fn process_single_slashing(
   911→    balance: &mut Cow<u64>,
   912→    validator: &Validator,
   913→    slashings_ctxt: &SlashingsContext,
   914→    state_ctxt: &StateContext,
   915→    spec: &ChainSpec,
   916→) -> Result<(), Error> {
   917→    if validator.slashed && slashings_ctxt.target_withdrawable_epoch == validator.withdrawable_epoch
   918→    {
   919→        let increment = spec.effective_balance_increment;
   920→        let penalty = if state_ctxt.fork_name.electra_enabled() {
   921→            let effective_balance_increments = validator.effective_balance.safe_div(increment)?;
   922→            slashings_ctxt
   923→                .penalty_per_effective_balance_increment
   924→                .safe_mul(effective_balance_increments)?
   925→        } else {
   926→            let penalty_numerator = validator
   927→                .effective_balance
   928→                .safe_div(increment)?
   929→                .safe_mul(slashings_ctxt.adjusted_total_slashing_balance)?;
   930→            penalty_numerator
   931→                .safe_div(state_ctxt.total_active_balance)?
   932→                .safe_mul(increment)?
   933→        };
   934→        *balance.make_mut()? = balance.saturating_sub(penalty);
   935→    }
   936→    Ok(())
   937→}
   938→
   939→impl PendingDepositsContext {
   940→    fn new<E: EthSpec>(
   941→        state: &BeaconState<E>,
   942→        spec: &ChainSpec,
   943→        config: &SinglePassConfig,
   944→    ) -> Result<Self, Error> {
   945→        let available_for_processing = state
   946→            .deposit_balance_to_consume()?
   947→            .safe_add(state.get_activation_exit_churn_limit(spec)?)?;
   948→        let current_epoch = state.current_epoch();
   949→        let next_epoch = state.next_epoch()?;
   950→        let mut processed_amount = 0;
   951→        let mut next_deposit_index = 0;
   952→        let mut validator_deposits_to_process = HashMap::new();
   953→        let mut deposits_to_postpone = vec![];
   954→        let mut new_validator_deposits = vec![];
   955→        let mut is_churn_limit_reached = false;
   956→        let finalized_slot = state
   957→            .finalized_checkpoint()
   958→            .epoch
   959→            .start_slot(E::slots_per_epoch());
   960→
   961→        let pending_deposits = state.pending_deposits()?;
   962→
   963→        for deposit in pending_deposits.iter() {
   964→            // Do not process deposit requests if the Eth1 bridge deposits are not yet applied.
   965→            if deposit.slot > spec.genesis_slot
   966→                && state.eth1_deposit_index() < state.deposit_requests_start_index()?
   967→            {
   968→                break;
   969→            }
   970→            // Do not process is deposit slot has not been finalized.
   971→            if deposit.slot > finalized_slot {
   972→                break;
   973→            }
   974→            // Do not process if we have reached the limit for the number of deposits
   975→            // processed in an epoch.
   976→            if next_deposit_index >= E::max_pending_deposits_per_epoch() {
   977→                break;
   978→            }
   979→            // We have to do a bit of indexing into `validators` here, but I can't see any way
   980→            // around that without changing the spec.
   981→            //
   982→            // We need to work out if `validator.exit_epoch` will be set to a non-default value
   983→            // *after* changes applied by `process_registry_updates`, which in our implementation
   984→            // does not happen until after this (but in the spec happens before). However it's not
   985→            // hard to work out: we don't need to know exactly what value the `exit_epoch` will
   986→            // take, just whether it is non-default. Nor do we need to know the value of
   987→            // `withdrawable_epoch`, because `next_epoch <= withdrawable_epoch` will evaluate to
   988→            // `true` both for the actual value & the default placeholder value (`FAR_FUTURE_EPOCH`).
   989→            let mut is_validator_exited = false;
   990→            let mut is_validator_withdrawn = false;
   991→            let opt_validator_index = state.pubkey_cache().get(&deposit.pubkey);
   992→            if let Some(validator_index) = opt_validator_index {
   993→                let validator = state.get_validator(validator_index)?;
   994→                let already_exited = validator.exit_epoch < spec.far_future_epoch;
   995→                // In the spec process_registry_updates is called before process_pending_deposits
   996→                // so we must account for process_registry_updates ejecting the validator for low balance
   997→                // and setting the exit_epoch to < far_future_epoch. Note that in the spec the effective
   998→                // balance update does not happen until *after* the registry update, so we don't need to
   999→                // account for changes to the effective balance that would push it below the ejection
  1000→                // balance here.
  1001→                // Note: we only consider this if registry_updates are enabled in the config.
  1002→                // EF tests require us to run epoch_processing functions in isolation.
  1003→                let will_be_exited = config.registry_updates
  1004→                    && (validator.is_active_at(current_epoch)
  1005→                        && validator.effective_balance <= spec.ejection_balance);
  1006→                is_validator_exited = already_exited || will_be_exited;
  1007→                is_validator_withdrawn = validator.withdrawable_epoch < next_epoch;
  1008→            }
  1009→
  1010→            if is_validator_withdrawn {
  1011→                // Deposited balance will never become active. Queue a balance increase but do not
  1012→                // consume churn. Validator index must be known if the validator is known to be
  1013→                // withdrawn (see calculation of `is_validator_withdrawn` above).
  1014→                let validator_index =
  1015→                    opt_validator_index.ok_or(Error::PendingDepositsLogicError)?;
  1016→                validator_deposits_to_process
  1017→                    .entry(validator_index)
  1018→                    .or_insert(0)
  1019→                    .safe_add_assign(deposit.amount)?;
  1020→            } else if is_validator_exited {
  1021→                // Validator is exiting, postpone the deposit until after withdrawable epoch
  1022→                deposits_to_postpone.push(deposit.clone());
  1023→            } else {
  1024→                // Check if deposit fits in the churn, otherwise, do no more deposit processing in this epoch.
  1025→                is_churn_limit_reached =
  1026→                    processed_amount.safe_add(deposit.amount)? > available_for_processing;
  1027→                if is_churn_limit_reached {
  1028→                    break;
  1029→                }
  1030→                processed_amount.safe_add_assign(deposit.amount)?;
  1031→
  1032→                // Deposit fits in the churn, process it. Increase balance and consume churn.
  1033→                if let Some(validator_index) = state.pubkey_cache().get(&deposit.pubkey) {
  1034→                    validator_deposits_to_process
  1035→                        .entry(validator_index)
  1036→                        .or_insert(0)
  1037→                        .safe_add_assign(deposit.amount)?;
  1038→                } else {
  1039→                    // The `PendingDeposit` is for a new validator
  1040→                    new_validator_deposits.push(deposit.clone());
  1041→                }
  1042→            }
  1043→
  1044→            // Regardless of how the deposit was handled, we move on in the queue.
  1045→            next_deposit_index.safe_add_assign(1)?;
  1046→        }
  1047→
  1048→        // Accumulate churn only if the churn limit has been hit.
  1049→        let deposit_balance_to_consume = if is_churn_limit_reached {
  1050→            available_for_processing.safe_sub(processed_amount)?
  1051→        } else {
  1052→            0
  1053→        };
  1054→
  1055→        Ok(Self {
  1056→            next_deposit_index,
  1057→            deposit_balance_to_consume,
  1058→            validator_deposits_to_process,
  1059→            deposits_to_postpone,
  1060→            new_validator_deposits,
  1061→        })
  1062→    }
  1063→}
  1064→
  1065→fn process_pending_deposits_for_validator(
  1066→    balance: &mut Cow<u64>,
  1067→    validator_info: &ValidatorInfo,
  1068→    pending_balance_deposits_ctxt: &PendingDepositsContext,
  1069→) -> Result<(), Error> {
  1070→    if let Some(deposit_amount) = pending_balance_deposits_ctxt
  1071→        .validator_deposits_to_process
  1072→        .get(&validator_info.index)
  1073→    {
  1074→        balance.make_mut()?.safe_add_assign(*deposit_amount)?;
  1075→    }
  1076→    Ok(())
  1077→}
  1078→
  1079→/// Return the set of validators referenced by consolidations, either as source or target.
  1080→///
  1081→/// This function is blind to whether the consolidations are valid and capable of being processed,
  1082→/// it just returns the set of all indices present in consolidations. This is *sufficient* to
  1083→/// make consolidations play nicely with effective balance updates. The algorithm used is:
  1084→///
  1085→/// - In the single pass: apply effective balance updates for all validators *not* referenced by
  1086→///   consolidations.
  1087→/// - Apply consolidations.
  1088→/// - Apply effective balance updates for all validators previously skipped.
  1089→///
  1090→/// Prior to Electra, the empty set is returned.
  1091→fn get_validators_in_consolidations<E: EthSpec>(state: &BeaconState<E>) -> BTreeSet<usize> {
  1092→    let mut referenced_validators = BTreeSet::new();
  1093→
  1094→    if let Ok(pending_consolidations) = state.pending_consolidations() {
  1095→        for pending_consolidation in pending_consolidations {
  1096→            referenced_validators.insert(pending_consolidation.source_index as usize);
  1097→            referenced_validators.insert(pending_consolidation.target_index as usize);
  1098→        }
  1099→    }
  1100→
  1101→    referenced_validators
  1102→}
  1103→
  1104→/// We process pending consolidations after all of single-pass epoch processing, and then patch up
  1105→/// the effective balances for affected validators.
  1106→///
  1107→/// This is safe because processing consolidations does not depend on the `effective_balance`.
  1108→fn process_pending_consolidations<E: EthSpec>(
  1109→    state: &mut BeaconState<E>,
  1110→    validators_in_consolidations: &BTreeSet<usize>,
  1111→    next_epoch_cache: &mut PreEpochCache,
  1112→    effective_balances_ctxt: &EffectiveBalancesContext,
  1113→    perform_effective_balance_updates: bool,
  1114→    state_ctxt: &StateContext,
  1115→    spec: &ChainSpec,
  1116→) -> Result<(), Error> {
  1117→    let mut next_pending_consolidation: usize = 0;
  1118→    let next_epoch = state.next_epoch()?;
  1119→    let pending_consolidations = state.pending_consolidations()?.clone();
  1120→
  1121→    for pending_consolidation in &pending_consolidations {
  1122→        let source_index = pending_consolidation.source_index as usize;
  1123→        let target_index = pending_consolidation.target_index as usize;
  1124→        let source_validator = state.get_validator(source_index)?;
  1125→        if source_validator.slashed {
  1126→            next_pending_consolidation.safe_add_assign(1)?;
  1127→            continue;
  1128→        }
  1129→        if source_validator.withdrawable_epoch > next_epoch {
  1130→            break;
  1131→        }
  1132→
  1133→        // Calculate the consolidated balance
  1134→        let source_effective_balance = std::cmp::min(
  1135→            *state
  1136→                .balances()
  1137→                .get(source_index)
  1138→                .ok_or(BeaconStateError::UnknownValidator(source_index))?,
  1139→            source_validator.effective_balance,
  1140→        );
  1141→
  1142→        // Move active balance to target. Excess balance is withdrawable.
  1143→        decrease_balance(state, source_index, source_effective_balance)?;
  1144→        increase_balance(state, target_index, source_effective_balance)?;
  1145→
  1146→        next_pending_consolidation.safe_add_assign(1)?;
  1147→    }
  1148→
  1149→    state
  1150→        .pending_consolidations_mut()?
  1151→        .pop_front(next_pending_consolidation)?;
  1152→
  1153→    // the spec tests require we don't perform effective balance updates when testing pending_consolidations
  1154→    if !perform_effective_balance_updates {
  1155→        return Ok(());
  1156→    }
  1157→
  1158→    // Re-process effective balance updates for validators affected by consolidations.
  1159→    let (validators, balances, _, current_epoch_participation, _, progressive_balances, _, _) =
  1160→        state.mutable_validator_fields()?;
  1161→    for &validator_index in validators_in_consolidations {
  1162→        let balance = *balances
  1163→            .get(validator_index)
  1164→            .ok_or(BeaconStateError::UnknownValidator(validator_index))?;
  1165→        let mut validator = validators
  1166→            .get_cow(validator_index)
  1167→            .ok_or(BeaconStateError::UnknownValidator(validator_index))?;
  1168→        let validator_current_epoch_participation = *current_epoch_participation
  1169→            .get(validator_index)
  1170→            .ok_or(BeaconStateError::UnknownValidator(validator_index))?;
  1171→
  1172→        process_single_effective_balance_update(
  1173→            validator_index,
  1174→            balance,
  1175→            &mut validator,
  1176→            validator_current_epoch_participation,
  1177→            next_epoch_cache,
  1178→            progressive_balances,
  1179→            effective_balances_ctxt,
  1180→            state_ctxt,
  1181→            spec,
  1182→        )?;
  1183→    }
  1184→    Ok(())
  1185→}
  1186→
  1187→impl EffectiveBalancesContext {
  1188→    fn new(spec: &ChainSpec) -> Result<Self, Error> {
  1189→        let hysteresis_increment = spec
  1190→            .effective_balance_increment
  1191→            .safe_div(spec.hysteresis_quotient)?;
  1192→        let downward_threshold =
  1193→            hysteresis_increment.safe_mul(spec.hysteresis_downward_multiplier)?;
  1194→        let upward_threshold = hysteresis_increment.safe_mul(spec.hysteresis_upward_multiplier)?;
  1195→
  1196→        Ok(Self {
  1197→            downward_threshold,
  1198→            upward_threshold,
  1199→        })
  1200→    }
  1201→}
  1202→
  1203→/// This function is called for validators that do not have their effective balance updated as
  1204→/// part of the single-pass loop. For these validators we compute their true effective balance
  1205→/// update after processing consolidations. However, to maintain the invariants of the
  1206→/// `PreEpochCache` we must register _some_ effective balance for them immediately.
  1207→fn process_single_dummy_effective_balance_update(
  1208→    validator_index: usize,
  1209→    validator: &Cow<Validator>,
  1210→    next_epoch_cache: &mut PreEpochCache,
  1211→    state_ctxt: &StateContext,
  1212→) -> Result<(), Error> {
  1213→    // Populate the effective balance cache with the current effective balance. This will be
  1214→    // overriden when `process_single_effective_balance_update` is called.
  1215→    let is_active_next_epoch = validator.is_active_at(state_ctxt.next_epoch);
  1216→    let temporary_effective_balance = validator.effective_balance;
  1217→    next_epoch_cache.update_effective_balance(
  1218→        validator_index,
  1219→        temporary_effective_balance,
  1220→        is_active_next_epoch,
  1221→    )?;
  1222→    Ok(())
  1223→}
  1224→
  1225→/// This function abstracts over phase0 and Electra effective balance processing.
  1226→#[allow(clippy::too_many_arguments)]
  1227→fn process_single_effective_balance_update(
  1228→    validator_index: usize,
  1229→    balance: u64,
  1230→    validator: &mut Cow<Validator>,
  1231→    validator_current_epoch_participation: ParticipationFlags,
  1232→    next_epoch_cache: &mut PreEpochCache,
  1233→    progressive_balances: &mut ProgressiveBalancesCache,
  1234→    eb_ctxt: &EffectiveBalancesContext,
  1235→    state_ctxt: &StateContext,
  1236→    spec: &ChainSpec,
  1237→) -> Result<(), Error> {
  1238→    // Use the higher effective balance limit if post-Electra and compounding withdrawal credentials
  1239→    // are set.
  1240→    let effective_balance_limit = validator.get_max_effective_balance(spec, state_ctxt.fork_name);
  1241→
  1242→    let old_effective_balance = validator.effective_balance;
  1243→    let new_effective_balance = if balance.safe_add(eb_ctxt.downward_threshold)?
  1244→        < validator.effective_balance
  1245→        || validator
  1246→            .effective_balance
  1247→            .safe_add(eb_ctxt.upward_threshold)?
  1248→            < balance
  1249→    {
  1250→        min(
  1251→            balance.safe_sub(balance.safe_rem(spec.effective_balance_increment)?)?,
  1252→            effective_balance_limit,
  1253→        )
  1254→    } else {
  1255→        validator.effective_balance
  1256→    };
  1257→
  1258→    let is_active_next_epoch = validator.is_active_at(state_ctxt.next_epoch);
  1259→
  1260→    if new_effective_balance != old_effective_balance {
  1261→        validator.make_mut()?.effective_balance = new_effective_balance;
  1262→
  1263→        // Update progressive balances cache for the *current* epoch, which will soon become the
  1264→        // previous epoch once the epoch transition completes.
  1265→        progressive_balances.on_effective_balance_change(
  1266→            validator.slashed,
  1267→            validator_current_epoch_participation,
  1268→            old_effective_balance,
  1269→            new_effective_balance,
  1270→        )?;
  1271→    }
  1272→
  1273→    // Caching: update next epoch effective balances and total active balance.
  1274→    next_epoch_cache.update_effective_balance(
  1275→        validator_index,
  1276→        new_effective_balance,
  1277→        is_active_next_epoch,
  1278→    )?;
  1279→
  1280→    Ok(())
  1281→}
